CREATE OR REPLACE FUNCTION public.set_role_permissions(p_role_id uuid,p_permission_ids uuid[]) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_tenant uuid; BEGIN SELECT tenant_id INTO v_tenant FROM public.roles WHERE id=p_role_id AND is_system_role=false; IF v_tenant IS NULL THEN RAISE EXCEPTION 'ROLE_NOT_EDITABLE'; END IF; IF NOT public.has_tenant_permission(v_tenant,'roles:manage') THEN RAISE EXCEPTION 'PERMISSION_DENIED'; END IF; IF v_tenant<>public.get_current_tenant_id() THEN RAISE EXCEPTION 'ROLE_WRONG_TENANT'; END IF; DELETE FROM public.role_permissions WHERE role_id=p_role_id; INSERT INTO public.role_permissions(role_id,permission_id) SELECT p_role_id,x FROM unnest(COALESCE(p_permission_ids,'{}'::uuid[])) x WHERE EXISTS(SELECT 1 FROM public.permissions p WHERE p.id=x) ON CONFLICT DO NOTHING; END; $$;
REVOKE ALL ON FUNCTION public.set_role_permissions(uuid,uuid[]) FROM PUBLIC;GRANT EXECUTE ON FUNCTION public.set_role_permissions(uuid,uuid[]) TO authenticated;
